begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.uid(n integer)returns uuid language sql immutable as $$select ('19110000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)
select pg_temp.uid(n),'authenticated','authenticated','publisher-s191-'||n||'@veyocast.test','test',now(),now(),now(),'{}','{}'from generate_series(1,3)n;
insert into public.profiles(id,display_name)select pg_temp.uid(n),'Publisher test '||n from generate_series(1,3)n;
insert into public.tenants(id,name,slug,screen_limit)values(pg_temp.uid(10),'Publisher A','publisher-s191-a',5),(pg_temp.uid(11),'Publisher B','publisher-s191-b',5);
insert into public.tenant_settings(tenant_id)values(pg_temp.uid(10)),(pg_temp.uid(11));
insert into public.tenant_memberships(tenant_id,user_id,role)values(pg_temp.uid(10),pg_temp.uid(1),'tenant_owner'),(pg_temp.uid(11),pg_temp.uid(2),'tenant_owner'),(pg_temp.uid(10),pg_temp.uid(3),'tenant_viewer');
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)
select pg_temp.uid(n),pg_temp.uid(case when n=21 then 11 else 10 end),'image','Ready photo '||n,'photo.webp','image/webp','ready',
 'tenants/'||pg_temp.uid(case when n=21 then 11 else 10 end)||'/assets/'||pg_temp.uid(n)||'/original.webp',2048,repeat('a',64),1920,1080 from generate_series(20,23)n;
insert into public.media_variants(tenant_id,asset_id,variant_type,storage_path,mime_type,file_size_bytes,checksum_sha256,width,height)
select tenant_id,id,'original',storage_path,mime_type,file_size_bytes,checksum_sha256,width,height from public.media_assets where id in(pg_temp.uid(20),pg_temp.uid(21),pg_temp.uid(22));
insert into public.playlists(id,tenant_id,name,created_by,updated_by,default_fit_mode,default_transition,default_video_muted,default_background_color)
select pg_temp.uid(n),pg_temp.uid(case when n=33 then 11 else 10 end),'Playlist '||n,pg_temp.uid(case when n=33 then 2 else 1 end),pg_temp.uid(case when n=33 then 2 else 1 end),'cover','crossfade',false,'#03438a'from generate_series(30,33)n;
insert into public.screens(id,tenant_id,name)values(pg_temp.uid(40),pg_temp.uid(10),'Three zone screen'),(pg_temp.uid(41),pg_temp.uid(10),'Second batch screen'),(pg_temp.uid(42),pg_temp.uid(11),'Other screen');
create temporary table command_results(name text primary key,value jsonb);grant all on command_results to authenticated,service_role;
create function pg_temp.batch(p_operations jsonb,p_key integer,p_playlist integer default 30,p_revision bigint default null)returns jsonb language sql as $$select public.mutate_playlist_batch_v1(pg_temp.uid(p_playlist),coalesce(p_revision,(select revision from public.playlists where id=pg_temp.uid(p_playlist))),p_operations,pg_temp.uid(p_key))$$;
create function pg_temp.composition(p_main integer default 30,p_side integer default 31)returns jsonb language sql as $$select jsonb_build_object('schemaVersion',1,'orientation','portrait','layout','three','mainWidthPercent',70,'bottomHeightPercent',20,'zones',jsonb_build_array(jsonb_build_object('id','main','playlistId',pg_temp.uid(p_main)),jsonb_build_object('id','side','playlistId',pg_temp.uid(p_side)),jsonb_build_object('id','bottom','playlistId',pg_temp.uid(30))))$$;
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
insert into command_results values('add',pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_media','clientId',pg_temp.uid(60),'mediaAssetId',pg_temp.uid(20),'durationSeconds',3)),100));
select is((select value->>'outcome'from command_results where name='add'),'applied','a verified photograph can be placed for three seconds');
select is((select duration_seconds from public.playlist_items where playlist_id=pg_temp.uid(30)),3,'requested duration survives legacy command defaults');
select ok((select fit_mode='cover'and transition='crossfade'and muted=false and background_color='#03438a'from public.playlist_items where playlist_id=pg_temp.uid(30)),'new media receives playlist defaults');
select is(pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_media','clientId',pg_temp.uid(60),'mediaAssetId',pg_temp.uid(20),'durationSeconds',3)),100,30,0),(select value from command_results where name='add'),'retry acknowledges the original command without duplicate media');
select is((select count(*)from public.playlist_items where playlist_id=pg_temp.uid(30)),1::bigint,'a retried save adds one placement');
create function pg_temp.sites_configuration()returns jsonb language sql immutable as $$select '{"schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","themeId":"onzetrots-tv","orientation":"landscape","provider":"sportlink","title":"Stand","subtitle":"","overlay":25,"accent":"#03438a","layout":"full","scale":100,"align":"left","safeArea":4,"seconds":15,"rowsPerPage":8,"ledTheme":"blue","ledMoment":"live","ledSide":"unknown","titleScale":100,"scoreScale":100,"logoScale":100,"teamScale":100,"showBranding":true,"showSceneLabel":true,"showClock":true,"showTimeline":true,"timelineLimit":3,"backgroundFit":"contain","grunge":55,"animation":"rise"}'::jsonb$$;
select throws_ok($$update public.playlist_items set sites_configuration_json='{}'where playlist_id=pg_temp.uid(30)$$,'23514',null,'direct authenticated update cannot bypass the typed placement boundary');
select throws_ok($$update public.playlist_items set sites_configuration_json=jsonb_set(pg_temp.sites_configuration(),'{schemaVersion}','"1"')where playlist_id=pg_temp.uid(30)$$,'23514',null,'direct update rejects string schema version');
select throws_ok($$update public.playlist_items set sites_configuration_json=pg_temp.sites_configuration()||'{"background":{}}'where playlist_id=pg_temp.uid(30)$$,'23514',null,'empty background cannot bypass asset identity validation');
select throws_ok($$update public.playlist_items set sites_configuration_json=pg_temp.sites_configuration()||'{"background":{"kind":"unknown"}}'where playlist_id=pg_temp.uid(30)$$,'23514',null,'unknown background cannot create unplayable published content');
select throws_ok($$update public.playlist_items set sites_configuration_json=pg_temp.sites_configuration()||jsonb_build_object('background',jsonb_build_object('kind','tenant','mediaAssetId',pg_temp.uid(21),'checksumSha256',repeat('a',64)))where playlist_id=pg_temp.uid(30)$$,'23514',null,'direct update rejects a verified background owned by another tenant');
select lives_ok($$update public.playlist_items set sites_configuration_json=pg_temp.sites_configuration()where playlist_id=pg_temp.uid(30)$$,'direct RLS writer can persist a valid normalized configuration');
select lives_ok($$update public.playlist_items set sites_configuration_json=null where playlist_id=pg_temp.uid(30)$$,'legacy null placement remains supported');
select is(pg_temp.batch('[{"operation":"details","name":"Stale edit","description":""}]',101,30,0)->>'outcome','conflict','a second authoring session receives revision conflict');
select is((select name from public.playlists where id=pg_temp.uid(30)),'Playlist 30','stale session cannot overwrite the name');
select throws_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_media','clientId',pg_temp.uid(61),'mediaAssetId',pg_temp.uid(23),'durationSeconds',10)),102)$$,'23514',null,'ready status alone cannot authorize unverified media');
select throws_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_media','clientId',pg_temp.uid(61),'mediaAssetId',pg_temp.uid(21),'durationSeconds',10)),103)$$,'23514',null,'media from tenant B cannot be added to tenant A');
select throws_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','details','name','First mutation','description','would change'),jsonb_build_object('operation','add_media','clientId',pg_temp.uid(61),'mediaAssetId',pg_temp.uid(23),'durationSeconds',10)),104)$$,'23514',null,'a later invalid selection rolls back the complete mixed command');
select is((select name from public.playlists where id=pg_temp.uid(30)),'Playlist 30','an earlier details edit is rolled back on later failure');
select is((select revision from public.playlists where id=pg_temp.uid(30)),1::bigint,'a rejected transaction does not advance the authoring revision');
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','patch','itemId',(select id from public.playlist_items where playlist_id=pg_temp.uid(30)),'patch',jsonb_build_object('cropFocusX',0.2,'volumePercent',37,'accessibilityName','Clubfoto')),jsonb_build_object('operation','duplicate','itemId',(select id from public.playlist_items where playlist_id=pg_temp.uid(30)),'clientId',pg_temp.uid(62))),105)$$,'partial rich settings and duplicate are applied together');
select ok((select bool_and(duration_seconds=3 and crop_focus_x=0.2 and volume_percent=37 and accessibility_name='Clubfoto'and fit_mode='cover')from public.playlist_items where playlist_id=pg_temp.uid(30)),'duplication keeps three seconds, crop, audio, accessibility and fit');
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','patch','itemId',(select id from public.playlist_items where playlist_id=pg_temp.uid(30)order by sort_order limit 1),'patch',jsonb_build_object('displayTitle','New title'))),106)$$,'title-only patch is accepted');
select ok((select bool_and(crop_focus_x=0.2 and volume_percent=37)from public.playlist_items where playlist_id=pg_temp.uid(30)),'a title-only edit leaves hidden presentation settings intact');
select throws_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','reorder','itemIds',jsonb_build_array((select id from public.playlist_items where playlist_id=pg_temp.uid(30)limit 1)))),107)$$,'23514',null,'reorder cannot silently discard an omitted placement');
select lives_ok($$select pg_temp.batch(jsonb_build_array(jsonb_build_object('operation','add_media','clientId',pg_temp.uid(63),'mediaAssetId',pg_temp.uid(22),'durationSeconds',7)),108,31)$$,'second real playlist receives verified media');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
insert into command_results values('release-main',to_jsonb(private.materialize_playlist_configuration_s185(pg_temp.uid(30)))),('release-side',to_jsonb(private.materialize_playlist_configuration_s185(pg_temp.uid(31))));
select is((select count(*)from public.playlist_release_items where playlist_id=pg_temp.uid(30)),2::bigint,'publication contains every three-second item');
insert into public.player_devices(id,tenant_id,screen_id,token_hash,paired_at)values(pg_temp.uid(50),pg_temp.uid(10),pg_temp.uid(40),repeat('e',64),now());
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
insert into command_results values('composition-save',public.save_screen_composition_draft_v1(pg_temp.uid(40),0,pg_temp.composition(),pg_temp.uid(110)));
select is((select value->>'outcome'from command_results where name='composition-save'),'saved','three zones are stored as a revision-guarded draft');
select is(public.save_screen_composition_draft_v1(pg_temp.uid(40),0,pg_temp.composition(),pg_temp.uid(111))->>'outcome','conflict','concurrent composition draft is rejected');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,pg_temp.composition(30,33),pg_temp.uid(112))$$,'23514',null,'a composition cannot bind a playlist from another tenant');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,jsonb_set(pg_temp.composition(),'{mainWidthPercent}','71'),pg_temp.uid(113))$$,'23514',null,'composition percentages follow the five-percent geometry steps');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,jsonb_set(pg_temp.composition(),'{mainWidthPercent}','null'),pg_temp.uid(213))$$,'23514',null,'JSON-null width cannot create an unplayable composition');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,jsonb_set(pg_temp.composition(),'{bottomHeightPercent}','null'),pg_temp.uid(214))$$,'23514',null,'JSON-null height cannot create an unplayable composition');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,jsonb_set(pg_temp.composition(),'{schemaVersion}','"1"'),pg_temp.uid(215))$$,'23514',null,'string schema version cannot bypass the typed Player contract');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,jsonb_set(pg_temp.composition(),'{mainWidthPercent}','"70"'),pg_temp.uid(216))$$,'23514',null,'string width cannot bypass the typed Player contract');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,pg_temp.composition()-'orientation',pg_temp.uid(217))$$,'23514',null,'missing orientation cannot create an unplayable composition');
select is((select revision from public.screen_composition_drafts where screen_id=pg_temp.uid(40)),1::bigint,'invalid typed compositions preserve the previous draft and revision');
insert into command_results values('composition-publish',public.publish_screen_composition_v1(pg_temp.uid(40),1,pg_temp.uid(114)));
select is((select value->>'outcome'from command_results where name='composition-publish'),'published','all three verified releases publish as one composition');
select is((select count(*)from public.screen_composition_bindings),3::bigint,'immutable composition freezes every zone');
select is((select orientation from public.screens where id=pg_temp.uid(40)),'portrait','orientation activates with the complete composition');
select is((select active_composition_id from public.player_devices where id=pg_temp.uid(50)),null::uuid,'publication alone never claims a player frame acknowledgement');
select is((select desired_composition_id from public.player_devices where id=pg_temp.uid(50)),(select composition_id from public.screens where id=pg_temp.uid(40)),'paired player receives the desired complete composition');
select throws_ok($$update public.screen_compositions set configuration_json='{}'where screen_id=pg_temp.uid(40)$$,'42501',null,'browser cannot mutate an immutable publication');
select throws_ok($$select public.save_publish_screen_composition_batch_v1(pg_temp.uid(10),jsonb_build_array(jsonb_build_object('screenId',pg_temp.uid(41),'expectedDraftRevision',0,'configuration',pg_temp.composition()),jsonb_build_object('screenId',pg_temp.uid(40),'expectedDraftRevision',999,'configuration',pg_temp.composition())),pg_temp.uid(115))$$,'40001',null,'multi-screen save and publish roll back when a later target conflicts');
select is((select count(*)from public.screen_compositions where screen_id=pg_temp.uid(41)),0::bigint,'earlier screen in a conflicting batch receives no publication');
select is((select count(*)from public.screen_composition_drafts where screen_id=pg_temp.uid(41)),0::bigint,'earlier screen receives no partial draft either');
select is((public.list_publisher_playlists_v1(pg_temp.uid(10),0,null,'all','items','assigned')->>'total')::integer,2,'library assignment counts include side and bottom zones');
select is((public.list_publisher_playlists_v1(pg_temp.uid(10),0,'Playlist 31','all','name','all')->'rows'->0->>'totalDurationSeconds')::integer,7,'library reports actual full durations without counting preview covers');
select throws_ok($$select public.mutate_playlist_library_batch_v1(pg_temp.uid(10),'archive',jsonb_build_array(jsonb_build_object('id',pg_temp.uid(31),'expectedRevision',(select revision from public.playlists where id=pg_temp.uid(31)))),pg_temp.uid(116))$$,'23514',null,'assigned side content cannot be archived');
select throws_ok($$select public.mutate_playlist_library_batch_v1(pg_temp.uid(10),'archive',jsonb_build_array(jsonb_build_object('id',pg_temp.uid(32),'expectedRevision',0),jsonb_build_object('id',pg_temp.uid(31),'expectedRevision',999)),pg_temp.uid(117))$$,'40001',null,'bulk library action rolls back earlier rows on a later conflict');
select is((select status::text from public.playlists where id=pg_temp.uid(32)),'draft','bulk conflict preserves the earlier playlist status');
insert into command_results values('library-archive',public.mutate_playlist_library_batch_v1(pg_temp.uid(10),'archive',jsonb_build_array(jsonb_build_object('id',pg_temp.uid(32),'expectedRevision',0)),pg_temp.uid(118)));
select is((select status::text from public.playlists where id=pg_temp.uid(32)),'archived','unassigned playlist is archived by a guarded batch');
select is(public.mutate_playlist_library_batch_v1(pg_temp.uid(10),'archive',jsonb_build_array(jsonb_build_object('id',pg_temp.uid(32),'expectedRevision',0)),pg_temp.uid(118)),(select value from command_results where name='library-archive'),'bulk retry acknowledges rather than repeating its mutation');
select lives_ok($$select public.mutate_playlist_library_batch_v1(pg_temp.uid(10),'restore',jsonb_build_array(jsonb_build_object('id',pg_temp.uid(32),'expectedRevision',1)),pg_temp.uid(119))$$,'archived playlist restores to an editable draft');
select throws_ok($$select public.mutate_playlist_library_batch_v1(pg_temp.uid(10),'duplicate',jsonb_build_array(jsonb_build_object('id',pg_temp.uid(30),'expectedRevision',999)),pg_temp.uid(120))$$,'40001',null,'stale duplicate is rejected without creating a phantom playlist');
select is((select count(*)from public.playlists),3::bigint,'tenant A library excludes actual tenant B records');
select set_config('request.jwt.claim.sub',pg_temp.uid(2)::text,true);
select is((select count(*)from public.screen_composition_bindings),0::bigint,'tenant B cannot read existing tenant A composition bindings');
select throws_ok($$select public.save_screen_composition_draft_v1(pg_temp.uid(40),1,pg_temp.composition(),pg_temp.uid(121))$$,'42501',null,'tenant B cannot write tenant A composition');
select throws_ok($$select public.list_publisher_playlists_v1(pg_temp.uid(10))$$,'42501',null,'tenant B cannot query tenant A library aggregates');
select throws_ok($$select pg_temp.batch('[{"operation":"details","name":"Cross tenant","description":""}]',122,30,0)$$,'42501',null,'tenant B cannot submit a tenant A mixed authoring command');
select set_config('request.jwt.claim.sub',pg_temp.uid(3)::text,true);
select throws_ok($$select pg_temp.batch('[{"operation":"details","name":"Viewer write","description":""}]',123)$$,'42501',null,'tenant viewer cannot submit mixed writes');
reset role;
select ok(private.publication_release_is_referenced_v1(pg_temp.uid(10),((select value from command_results where name='release-side')#>>'{}')::uuid),'retention protects the frozen side release');
insert into command_results select 'composition-target',jsonb_build_object('id',composition_id,'revision',target_revision)from public.screens where id=pg_temp.uid(40);
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select is(public.acknowledge_player_composition_v1(repeat('e',64),pg_temp.uid(999),1),false,'an old or unknown composition cannot be acknowledged');
select is(public.acknowledge_player_composition_v1(repeat('e',64),(select(value->>'id')::uuid from command_results where name='composition-target'),(select(value->>'revision')::bigint-1 from command_results where name='composition-target')),false,'a stale target revision cannot acknowledge a frame');
select is(public.acknowledge_player_composition_v1(repeat('e',64),(select(value->>'id')::uuid from command_results where name='composition-target'),(select(value->>'revision')::bigint from command_results where name='composition-target')),true,'verified current player target can acknowledge the complete composition');
reset role;
select is((select active_composition_id from public.player_devices where id=pg_temp.uid(50)),(select composition_id from public.screens where id=pg_temp.uid(40)),'frame acknowledgement advances the actual active composition');
select throws_ok($$update public.screen_compositions set configuration_json='{}'where screen_id=pg_temp.uid(40)$$,'23514',null,'even the owner cannot modify a published composition');

-- Club profile authoring uses the same server acknowledgement and CAS rules.
select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
set local role authenticated;
insert into command_results values('settings',public.update_tenant_control_settings_v4(pg_temp.uid(10),'Publisher A','#03438a',10,'contain',true,'landscape',1920,1080,'Europe/Amsterdam','cut',null,'Clubgebouw','https://club.veyocast.test',0,pg_temp.uid(130)));
select is((select value->>'outcome'from command_results where name='settings'),'saved','club location and website are saved through a guarded command');
select is((select club_location from public.tenant_settings where tenant_id=pg_temp.uid(10)),'Clubgebouw','saved club details load from the database');
select is(public.update_tenant_control_settings_v4(pg_temp.uid(10),'Publisher A','#03438a',10,'contain',true,'landscape',1920,1080,'Europe/Amsterdam','cut',null,'Clubgebouw','https://club.veyocast.test',0,pg_temp.uid(130)),(select value from command_results where name='settings'),'settings retry does not repeat or overwrite a later revision');
select is(public.update_tenant_control_settings_v4(pg_temp.uid(10),'Publisher A','#03438a',10,'contain',true,'landscape',1920,1080,'Europe/Amsterdam','cut',null,'Stale location','https://club.veyocast.test',0,pg_temp.uid(131))->>'outcome','conflict','stale club edit receives an explicit conflict');

-- Calendar deletion preserves provenance and immediately chooses a safe main target.
insert into command_results values('schedule-payload',jsonb_build_object('name','Live match schedule','targetKind','screen','targetId',pg_temp.uid(40),'releaseId',(select value from command_results where name='release-side'),'timezoneName','Europe/Amsterdam','scheduleKind','once','startsAt',now()-interval '1 minute','endsAt',now()+interval '1 hour','enabled',true,'calendarTone','blue'));
insert into command_results values('schedule',public.mutate_content_schedule_v2(pg_temp.uid(10),null,0,'create',(select value from command_results where name='schedule-payload'),pg_temp.uid(140)));
select is((select value->>'outcome'from command_results where name='schedule'),'applied','real schedule is created with the chosen calendar colour');
select is((select calendar_tone from public.content_schedules where id=(select(value->>'scheduleId')::uuid from command_results where name='schedule')),'blue','calendar colour survives reload');
reset role;set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select lives_ok($$select public.apply_due_content_schedules_v1(now())$$,'worker activates the scheduled main release');
reset role;
select is((select assigned_playlist_id from public.screens where id=pg_temp.uid(40)),pg_temp.uid(31),'active schedule replaces the main playlist');
select is((select count(*)from public.screen_composition_bindings where zone_id in('side','bottom')),2::bigint,'schedule activation preserves side and bottom zones');
set local role authenticated;
select lives_ok($$select public.save_publish_screen_composition_batch_v1(pg_temp.uid(10),jsonb_build_array(jsonb_build_object('screenId',pg_temp.uid(40),'expectedDraftRevision',1,'configuration',pg_temp.composition())),pg_temp.uid(141))$$,'a new default composition can be published during a schedule');
select is((select assigned_playlist_id from public.screens where id=pg_temp.uid(40)),pg_temp.uid(31),'changing the default does not end the active main schedule');
insert into command_results values('schedule-delete',public.mutate_content_schedule_v2(pg_temp.uid(10),(select(value->>'scheduleId')::uuid from command_results where name='schedule'),0,'delete','{}',pg_temp.uid(142)));
select is((select value->>'outcome'from command_results where name='schedule-delete'),'deleted','calendar delete is acknowledged with an authoring revision');
select is((select count(*)from public.content_schedules where deleted_at is null),0::bigint,'deleted schedule leaves the actual calendar query');
select is((select assigned_playlist_id from public.screens where id=pg_temp.uid(40)),pg_temp.uid(30),'deleting an active schedule restores the current default main release');
select is((select active_schedule_id from public.screens where id=pg_temp.uid(40)),null::uuid,'the removed schedule is no longer active');
select ok((select count(*)>0 from public.publisher_target_snapshots where schedule_id=(select(value->>'scheduleId')::uuid from command_results where name='schedule')),'delete preserves immutable publication target provenance');
select is(public.mutate_content_schedule_v2(pg_temp.uid(10),(select(value->>'scheduleId')::uuid from command_results where name='schedule'),0,'delete','{}',pg_temp.uid(142)),(select value from command_results where name='schedule-delete'),'delete retries acknowledge the first command');
select throws_ok($$select public.mutate_content_schedule_v1(pg_temp.uid(10),(select(value->>'scheduleId')::uuid from command_results where name='schedule'),1,'enable','{}',pg_temp.uid(143))$$,'23514',null,'legacy enable cannot revive a deleted schedule');
insert into command_results values('schedule-all',public.mutate_content_schedule_v2(pg_temp.uid(10),null,0,'create_all',(select value||jsonb_build_object('name','Every screen','calendarTone','petrol','startsAt',now()+interval '2 hours','endsAt',now()+interval '3 hours')from command_results where name='schedule-payload'),pg_temp.uid(144)));
select is((select(value->>'targetCount')::integer from command_results where name='schedule-all'),2,'all-screen command resolves exactly the active screens in this tenant');
select is((select count(*)from public.content_schedules where deleted_at is null and calendar_tone='petrol'),2::bigint,'all targets receive the real saved schedule');
select is((select count(*)from public.content_schedules where tenant_id=pg_temp.uid(11)),0::bigint,'all-screen selection never schedules another tenant');
select throws_ok($$select public.mutate_content_schedule_v2(pg_temp.uid(10),null,0,'create_all',(select value||jsonb_build_object('releaseId',pg_temp.uid(999))from command_results where name='schedule-payload'),pg_temp.uid(145))$$,'23514',null,'unavailable all-screen release causes a complete rollback');
select is((select count(*)from public.content_schedules where deleted_at is null),2::bigint,'failed bulk scheduling creates no partial rows');
